INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptaufgabe eines Datenschutzbeauftragten?', 3, '[{"text": "Überwachung der Datenschutzvorschriften", "correct": true, "because": "Kernaufgabe nach DSGVO"}, {"text": "Hardware warten", "correct": false, "because": "Kein technischer Fokus"}, {"text": "Netzwerk sichern", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ab wie vielen Mitarbeitern ist in Deutschland ein Datenschutzbeauftragter Pflicht?', 2, '[{"text": "20", "correct": true, "because": "§ 38 BDSG"}, {"text": "10", "correct": false, "because": "Alte Regelung"}, {"text": "50", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen muss ein Datenschutzbeauftragter erfüllen?', 5, '[{"text": "Fachwissen im Datenschutzrecht", "correct": true, "because": "Art. 37 DSGVO"}, {"text": "IT-Kenntnisse", "correct": true, "because": "Praxisrelevant"}, {"text": "Grafikdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datenschutzbeauftragter muss unabhängig sein. b) Er ist immer extern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann auch intern sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bestellung eines Datenschutzbeauftragten?', 4, '[{"text": "Fachkunde", "correct": false, "because": "Gesetzlich gefordert"}, {"text": "Interessenkonflikte", "correct": false, "because": "Müssen vermieden werden"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Geschäftsführer Datenschutzbeauftragter sein?', 2, '[{"text": "Nein", "correct": true, "because": "Interessenkonflikt"}, {"text": "Ja", "correct": false, "because": "Unabhängigkeit verletzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Datenschutzbeauftragter nach DSGVO?', 3, '[{"text": "Beratung zu Datenschutzfragen", "correct": true, "because": "Art. 39 DSGVO"}, {"text": "Software programmieren", "correct": false, "because": "Kein Programmierfokus"}, {"text": "Server warten", "correct": false, "because": "Technische Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Datenschutzbeauftragter?', 5, '[{"text": "Weisungsfreiheit", "correct": true, "because": "Art. 38 DSGVO"}, {"text": "Kündigungsschutz", "correct": true, "because": "§ 6 BDSG"}, {"text": "Netzwerkadministration", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Datenschutzbeauftragter muss der Aufsichtsbehörde gemeldet werden. b) Er ist für Verstöße haftbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unternehmen haftet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Rolle eines Datenschutzbeauftragten?', 4, '[{"text": "Datenschutzkenntnisse", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Kommunikationsfähigkeit", "correct": false, "because": "Für Beratung nötig"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Datenschutzbeauftragter intern sein?', 2, '[{"text": "Nein", "correct": true, "because": "Extern möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel wählbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmen brauchen einen Datenschutzbeauftragten?', 4, '[{"text": "Öffentliche Stellen", "correct": true, "because": "Art. 37 DSGVO"}, {"text": "Firmen mit über 20 Datenverarbeitern", "correct": true, "because": "§ 38 BDSG"}, {"text": "Einzelhändler ohne Daten", "correct": false, "because": "Keine Verpflichtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Datenschutzbeauftragter keine Schulungen macht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schulung ist Aufgabe"}, {"text": "Ja", "correct": false, "because": "Art. 39 DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Datenschutzbeauftragten?', 3, '[{"text": "Fachwissen", "correct": true, "because": "Gesetzlich gefordert"}, {"text": "Schnelle Verfügbarkeit", "correct": false, "because": "Kompetenz wichtiger"}, {"text": "Geringe Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datenschutzbeauftragter berät zur DSGVO. b) Er ist für die IT-Sicherheit verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IT-Sicherheit nicht Kernaufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat ein Unternehmen gegenüber dem Datenschutzbeauftragten?', 5, '[{"text": "Unterstützung gewähren", "correct": true, "because": "Art. 38 DSGVO"}, {"text": "Frühzeitige Einbindung", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Hardware warten", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Rolle unwichtig?', 3, '[{"text": "Fachkenntnisse", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Unabhängigkeit", "correct": false, "because": "Gesetzlich gefordert"}, {"text": "Bildschirmdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Datenschutzbeauftragter abberufen werden?', 3, '[{"text": "Ja", "correct": true, "because": "Aber nur mit Grund"}, {"text": "Nein", "correct": false, "because": "Schutz besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Datenschutzbeauftragter extern sein?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 37 DSGVO erlaubt es"}, {"text": "Nein", "correct": false, "because": "Flexibel wählbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die DSGVO für den Datenschutzbeauftragten?', 4, '[{"text": "Legt Aufgaben fest", "correct": true, "because": "Art. 39 DSGVO"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Kein Netzwerkeffekt"}, {"text": "Verbessert Hardware", "correct": false, "because": "Irrelevant"}]');
